target.css:
:root {
  --ink: #24213a;
  --muted: #6c6880;
  --card: #fffdf8;
  --lavender: #eeeafd;
  --purple: #6655bd;
  --purple-dark: #4d3da1;
  --mint: #ccefdc;
  --mint-ink: #176447;
  --line: #ddd8ee;
  --cream: #fff3d6;
}

.claim-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.claim-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  background: var(--lavender);
  border-bottom: 1px solid var(--line);
}

.claim-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  font-size: 21px;
  background: var(--cream);
  border-radius: 12px;
}

.title-block {
  min-width: 0;
  flex: 1;
}

.eyebrow,
.panel-label {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.title-block h1 {
  margin: 3px 0 0;
  font-size: 19px;
  line-height: 1.1;
}

.status-badge {
  padding: 5px 9px;
  color: var(--mint-ink);
  background: var(--mint);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.claim-body {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 14px;
  padding: 14px 16px;
}

.item-panel {
  padding: 13px;
  background: var(--cream);
  border-radius: 12px;
}

.item-panel h2 {
  margin: 5px 0 3px;
  font-size: 17px;
  line-height: 1.15;
}

.description {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.35;
}

.claim-code {
  display: inline-block;
  margin-top: 10px;
  padding: 4px 7px;
  color: var(--purple-dark);
  background: var(--card);
  border: 1px dashed var(--purple);
  border-radius: 6px;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.pickup-details {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 2px 0;
  list-style: none;
}

.pickup-details li {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding-bottom: 7px;
  border-bottom: 1px solid var(--line);
}

.pickup-details li:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}

.pickup-details span {
  color: var(--muted);
  font-size: 11px;
}

.pickup-details strong {
  font-size: 13px;
  line-height: 1.2;
}

.claim-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 16px;
  border-top: 1px solid var(--line);
}

.claim-footer p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.3;
}

.actions {
  display: flex;
  flex-shrink: 0;
  gap: 7px;
}

.secondary-button,
.primary-button {
  padding: 7px 10px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
}

.secondary-button {
  color: var(--purple-dark);
  background: var(--card);
  border: 1px solid var(--line);
}

.primary-button {
  color: var(--card);
  background: var(--purple);
  border: 1px solid var(--purple);
}

